// src/components/layout/Sidebar.jsx
import React from 'react';

const StatCard = ({ label, value, unit }) => (
  <div className="bg-sidebar-card rounded-xl p-4">
    <p className="text-sm text-gray-600 font-medium">{label}</p>
    <p className="text-2xl font-semibold text-gray-900">
      {value ?? '...'} <span className="text-base font-normal text-gray-500 ml-1">{unit}</span>
    </p>
  </div>
);

const metricOrder = [
  { key: 'range', label: 'Range', unit: 'm' },
  { key: 'timeOfFlight', label: 'Time of Flight', unit: 's' },
  { key: 'peakHeight', label: 'Peak Height', unit: 'm' },
  { key: 'timeToPeak', label: 'Time to Peak', unit: 's' },
  { key: 'releaseSpeed', label: 'Release Speed', unit: 'm/s' },
  { key: 'releaseAngle', label: 'Release Angle', unit: '°' },
  { key: 'releaseHeight', label: 'Release Height', unit: 'm' },
];

const Sidebar = ({ isComparisonView, playerStats, throwDetails, comparisonStats, visibility, loading }) => {

  const renderSingleView = () => (
    <div className="p-6">
      {throwDetails && (
        <div className="mb-6">
          <h3 className="text-lg font-bold text-gray-900">{throwDetails.date}</h3>
          <p className="text-md text-gray-500">{`Throw ${throwDetails.throwNum} (${throwDetails.time})`}</p>
        </div>
      )}
      <h2 className="text-xl font-bold mb-4 text-gray-900">Performance Metrics</h2>
      <div className="space-y-3">
        {loading
          ? Array(7).fill(0).map((_, index) => <div key={index} className="bg-gray-100 rounded-xl p-4 h-20 animate-pulse"></div>)
          : metricOrder.map(metric => (
              <StatCard key={metric.key} label={metric.label} value={playerStats[metric.key]} unit={metric.unit} />
            ))}
      </div>
    </div>
  );

  const renderComparisonView = () => {
    const visibleStats = comparisonStats.filter(stat => visibility[stat.id]);
    
    return (
      <div className="flex flex-col h-full">
        <h2 className="text-xl font-bold text-gray-900 px-6 pt-6 pb-4 flex-shrink-0">
          Performance Comparison
        </h2>
        <div className="flex-1 overflow-auto px-6 pb-6">
          {visibleStats.length > 0 ? (
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b-2 border-gray-200">
                  <th className="py-3 pr-2 font-semibold text-gray-600 text-sm sticky top-0 bg-white">
                    Metric
                  </th>
                  {visibleStats.map(throwData => (
                    <th key={throwData.id} className="py-3 px-2 text-center font-semibold text-gray-800 sticky top-0 bg-white">
                      <div className="font-bold text-sm">{`${throwData.date.substring(5)}-${throwData.date.substring(2, 4)}`}</div>
                      <div className="text-xs text-gray-500 font-normal">{`#${throwData.throwNum} (${throwData.time})`}</div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {metricOrder.map(metric => (
                  <tr key={metric.key} className="border-b border-gray-100 last:border-b-0">
                    <td className="py-3 pr-2 font-semibold text-gray-600 text-sm">
                      {metric.label}
                    </td>
                    {visibleStats.map(throwData => (
                      <td key={throwData.id} className="py-3 px-2 text-center text-lg font-medium text-gray-900">
                        {throwData.playerStats[metric.key]}
                        <span className="text-xs font-normal text-gray-500 ml-1">{metric.unit}</span>
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
             <p className="text-gray-500 text-center mt-8">
                No throws are visible. Click a throw in the chart legend to show it.
            </p>
          )}
        </div>
      </div>
    );
  };

  return (
    <aside className="bg-white text-gray-800 h-full flex flex-col">
      <div className="h-16 flex-shrink-0 border-b border-gray-200 flex items-center px-6">
        <div className="flex items-center space-x-3">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-primary-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
          </svg>
          <span className="text-xl font-semibold text-gray-800">Javelin Tracker</span>
        </div>
      </div>
      <div className="flex-1 overflow-y-auto">
        {isComparisonView ? renderComparisonView() : renderSingleView()}
      </div>
    </aside>
  );
};

export default Sidebar;
